render=function(){enforceExposure();root.replaceChildren();updateQuick();if(!game){setup();return;}try{const g=game.s.global,v=game.view(),main=el('main'),body=el('div','content'),p=panel();main.append(sidebar(g,v),body);if(['STORY','LOCATION','HUB','MAIN_MENU','DIALOGUE'].includes(g.SCREEN_MODE)&&!game.s.runtime)body.append(scenePanel(v));body.append(p);root.append(main);if(game.s.runtime&&g.SCREEN_MODE!=='SYSTEM'&&!game.s.runtime.interlude){combat(p);return;}switch(g.SCREEN_MODE){case'COMBAT_PREP':battlePrepare(p);break;case'COMBAT_INTERLUDE':case'STORY_WAIT':case'STORY':story(p,v);break;case'DIALOGUE':dialogue(p,v);break;case'SHOP':shop(p,v);break;case'INVENTORY':inventory(p);break;case'PARTY':partyScreen(p);break;case'CRAFT':crafting(p);break;case'QUEST':quests(p,v);break;case'RELATIONS':relationsScreen(p,v);break;case'SYSTEM':system(p);break;case'REWARD':reward(p);break;case'BOSS_INTRO':boss(p);break;default:drawLocation(p,v)}}catch(e){const p=panel('이 장면을 표시하지 못했습니다');p.append(el('p','',e.message),button('현재 저장 백업 파일 내보내기',download),button('저장·설정',()=>act('MENU',{screen:'SYSTEM'})));root.append(p)}};
async function downloadOffline(status){if(!navigator.serviceWorker?.controller){status.textContent=('serviceWorker' in navigator?'오프라인 기능을 준비 중입니다. 잠시 뒤 다시 시도해 주세요.':'이 미리보기 주소에서는 오프라인 기능을 사용할 수 없습니다. 배포된 게임에서 이용해 주세요.');return;}status.textContent='콘텐츠 다운로드 중…';const channel=new MessageChannel();channel.port1.onmessage=e=>{const d=e.data;if(d.ok){window.CRPG_OFFLINE_READY=true;status.textContent='다운로드 및 검증 완료 · 오프라인 준비 완료'}else if(d.error)status.textContent='다운로드 실패: '+d.error;else status.textContent=`콘텐츠 다운로드 중… ${d.done} / ${d.total}`};navigator.serviceWorker.controller.postMessage({type:'DOWNLOAD_PACK'},[channel.port2])}
