window.CRPG_APP={get game(){return game},begin,act,render,loadState(s){game=new Runtime(DB,s);applySettings();render()},get settings(){return settings},get saveStore(){return saveStore}};
async function boot(){try{settings={...settings,...parseUI(localStorage.getItem('crpg-preferences-v3'))};}catch{}applySettings();if(window.CRPGSave?.SaveAdapter){saveStore=new CRPGSave.SaveAdapter({contentVersion:MANIFEST.saveCompatibilityVersion||MANIFEST.contentVersion,compatibleContentVersions:MANIFEST.compatibleSaveVersions||[],migrate:CRPGRelationships.migrateState,validate:s=>new Runtime(DB,s).s});try{await saveStore.open();const existing=await saveStore.list();const legacy=localStorage.getItem('crpg-latest');if(legacy&&!existing.some(x=>x.saveId===legacy)){await saveStore.importLegacyLocalStorage('legacy:'+legacy,{key:'crpg-save:'+legacy,name:'이전 저장'});}}catch(e){saveStore=null;say('이 브라우저의 자동 저장을 사용할 수 없습니다. 저장 백업 파일 내보내기를 이용해 주세요.')}}render();if('serviceWorker'in navigator&&location.protocol!=='file:'){try{const reg=await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='PACK_READY')window.CRPG_OFFLINE_READY=true});reg.active?.postMessage({type:'PACK_STATUS'});}catch(e){say('오프라인 기능을 시작하지 못했습니다. '+e.message)}}const context=document.modelContext;if(context?.registerTool){Promise.resolve(context.registerTool({name:'read_crpg_state',description:'현재 CRPG 화면과 선택 가능한 행동을 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){if(!game)return {screen:'TITLE'};const v=game.view();return {screen:game.s.global.SCREEN_MODE,location:v.map[2],speaker:v.node?.[7],text:v.node?.[9],choices:v.choices.map(c=>({id:c[4],label:c[10]}))}}})).catch(()=>{});}}
function chapterActions(p){if(game.actionReason('STORY_RESUME')&&game.playPhase()!=='FREE')return;for(const c of game.mainStoryEntries?.()||[]){if(c.available&&!c.reason)p.append(button(c.title||c.name||c.label||'메인 이야기 시작',()=>act('MAIN_STORY_ACCEPT',{quest:c.quest||c.id}),false,true));}if(game.s.global.STORY_WAITING){for(const c of game.storyChapterEntries?.()||[])p.append(button(c.title,()=>act('STORY_CHAPTER',{node:c.id}),false,true));if(game.s.global.STORY_NEXT_PREPARED)p.append(button('이야기 계속',()=>act('STORY_RESUME'),false,true))}}
const drawLocationLegacy=drawLocation;drawLocation=function(p,v){chapterActions(p);drawLocationLegacy(p,v)};
