function sceneClassification(){const ctx=game?.s.storyContext,def=ctx&&game.storyDefinition?.(ctx.entry);const kind=def?.RELATION_KIND||def?.AFFECTION_KIND;return {category:kind&&/ADULT/.test(kind)?'MATURE_ROMANCE':'GENERAL',verifiedClassification:!!kind,profileId:def?.PROFILE_ID};}
function scenePermitted(){const c=sceneClassification();return c.category==='GENERAL'||game?.canExposeRelationshipContent(c,c.profileId)===true;}
function enforceExposure(){if(!game||scenePermitted())return;const c=sceneClassification();game.invalidateRelationshipConsent?.('EXPOSURE_POLICY');game.s.relationshipInterrupted={entry:game.s.storyContext?.entry,reason:'EXPOSURE_POLICY'};game.s.storyContext=null;game.s.global.SCREEN_MODE='SYSTEM';}
function toolPreparation(p){
 const tools=game.rows('14_ITEM_DB').filter(r=>r[2]==='전술 도구'&&game.itemCount(r[0])>0);
 if(!tools.length)return;
 p.append(el('h2','','전투 도구 준비'),el('p','muted','다음 전투에서 사용할 도구를 '+game.tacticalCapacity()+'종까지 준비할 수 있습니다.'));
 const selected=new Set(game.s.preparedTools||[]);
 for(const r of tools){const label=el('label','settings-row'),check=el('input');check.type='checkbox';check.checked=selected.has(r[0]);check.onchange=()=>check.checked?selected.add(r[0]):selected.delete(r[0]);label.append(check,el('span','',r[1]+' · '+game.itemCount(r[0])+'개'));p.append(label)}
 const element=el('select');element.setAttribute('aria-label','원소 변환기 대기 원소');
 for(const [id,name]of [['NONE','원소 변환기 미설정'],['PYRO','불'],['HYDRO','물'],['ELECTRO','번개'],['CRYO','얼음'],['DENDRO','풀']]){const option=el('option','',name);option.value=id;element.append(option)}
 element.value=game.s.global.TACTICAL_ELEMENT_STANDBY||'NONE';p.append(element,button('도구 준비 저장',()=>act('TOOL_PREPARE',{items:[...selected],element:element.value}),false,true));
}
const inventoryWithParty=inventory;inventory=function(p){inventoryWithParty(p);toolPreparation(p)};
function bossProgressControls(p){const progress=game.s.bossRouteProgress;if(!progress||!['AWAIT_NEXT','RETRY'].includes(progress.phase))return;p.append(el('h2','','진행 중인 보스 도전'),el('p','',safeName('35_BOSS_ROUTE_DB',progress.route)+' · '+progress.step+'단계'));const reason=game.bossRecoveryReason?.();if(reason)p.append(el('p','muted',reason));actions(p,[button(progress.phase==='RETRY'?'해당 단계 재도전':'다음 전투로',()=>act('BOSS_CONTINUE'),false,true),button('도전에서 나가기',()=>act('BOSS_LEAVE'))]);}
const rewardWithLoot=reward;reward=function(p){rewardWithLoot(p);bossProgressControls(p)};
const bossWithEntry=boss;boss=function(p){if(['AWAIT_NEXT','RETRY'].includes(game.s.bossRouteProgress?.phase)){p.append(el('h1','','보스 도전'));bossProgressControls(p)}else bossWithEntry(p)};
const locationWithStory=drawLocation;drawLocation=function(p,v){locationWithStory(p,v);bossProgressControls(p)};
document.querySelector('.wordmark').addEventListener('click',event=>{event.preventDefault();fresh()});

